SD := Client.GetDocumentByPath('C:\Users\makarlistkov\Documents\Work\Engineering\FPGA-COURSE-WORK\ARTIX\ARTIX\libraries\ASV-50MHz\new\Schlib1.SchLib');
if SD <> Nil then begin

  L := Nil; if SD <> Nil then L := SchServer.GetSchDocumentByPath('C:\Users\makarlistkov\Documents\Work\Engineering\FPGA-COURSE-WORK\ARTIX\ARTIX\libraries\ASV-50MHz\new\Schlib1.SchLib');
  if L <> Nil then begin
    C := Nil; LI := L.SchLibIterator_Create;
    LI.AddFilter_ObjectSet(MkSet(eSchComponent)); LC := LI.FirstSchObject;
    while LC <> Nil do begin if LC.LibReference = 'ASV-50.000MHZ-LRS-T' then C := LC; LC := LI.NextSchObject; end;
    L.SchIterator_Destroy(LI);
    if C <> Nil then begin
      LogStep('select exact library component');
      if L.CurrentSchComponent.LibReference <> 'ASV-50.000MHZ-LRS-T' then L.CurrentSchComponent := C;
      C := L.CurrentSchComponent;
      if C.LibReference = 'ASV-50.000MHZ-LRS-T' then begin
        LogStep('load exact mm-to-internal layout'); Map:=TStringList.Create; V:=TStringList.Create;
Map.LoadFromFile('C:\Users\makarlistkov\Documents\Work\Engineering\FPGA-COURSE-WORK\output\altium\component-preparation\evidence\asv-layout-internal.txt');
F:=SchServer.FontManager.GetFontID(10,0,False,False,False,False,'GOST Common');
SchServer.ProcessControl.PreProcess(L,'');
try
C.PartCount:=1; C.DisplayMode:=0;
L.DisplayUnit:=eMM; L.SnapGridOn:=True; L.SnapGridSize:=393701; L.VisibleGridOn:=True; L.VisibleGridSize:=196850; L.HotSpotGridSize:=196850; L.SystemFont:=F;
I:=C.SchIterator_Create; I.AddFilter_ObjectSet(MkSet(ePin)); P:=I.FirstSchObject;
while P<>Nil do begin V.CommaText:=Map.Values[P.Designator]; P.OwnerPartId:=StrToInt(V[0]); P.OwnerPartDisplayMode:=0; P.Location:=Point(StrToInt(V[1]),StrToInt(V[2])); P.Orientation:=StrToInt(V[3]); P.PinLength:=1968504; P.SetState_Name_CustomFontID(F); P.SetState_Designator_CustomFontID(F); P.SetState_Name_FontMode(1); P.SetState_Designator_FontMode(1); P:=I.NextSchObject; end; C.SchIterator_Destroy(I);
LogStep('mm pin geometry applied; remove old graphic body'); N:=0; repeat I:=C.SchIterator_Create; I.AddFilter_ObjectSet(MkSet(eRectangle,eLabel,ePolyLine)); O:=I.FirstSchObject; C.SchIterator_Destroy(I); if O<>Nil then begin C.RemoveSchObject(O); L.RemoveSchObject(O); N:=N+1; end; until (O=Nil) or (N>=1000);
if N<1000 then begin
C.CurrentPartID:=1; R:=SchServer.SchObjectFactory(eRectangle,eCreate_Default); R.OwnerPartId:=1; R.OwnerPartDisplayMode:=0; R.Location:=Point(0,-6692913); R.Corner:=Point(25590551,787402); R.Color:=0; R.IsSolid:=False; R.LineWidth:=eSmall; C.AddSchObject(R);
T:=SchServer.SchObjectFactory(eLabel,eCreate_Default); T.OwnerPartId:=1; T.OwnerPartDisplayMode:=0; T.Text:='G'; T.Location:=Point(12795276,-393701); T.FontId:=F; T.Color:=0; T.Justification:=eJustify_Center; C.AddSchObject(T);
end;
C.Designator.FontId:=F; C.Comment.FontId:=F; C.Designator.Location:=Point(0,1968504); C.Comment.Location:=Point(5905512,1968504); C.Designator.IsHidden:=False; C.Comment.IsHidden:=True;
C.CurrentPartID:=1; C.PartIdLocked:=True; finally SchServer.ProcessControl.PostProcess(L,'Millimetre library layout'); end;
Map.Free; V.Free; SD.SetModified(True); L.GraphicallyInvalidate; LogStep('save mm symbol'); if N<1000 then begin if SD.DoFileSave('') then ResultText:='{"saved":true}' else ResultText:='{"error":"SAVE_FAILED"}'; end else ResultText:='{"error":"BODY_REMOVAL_LIMIT"}';
      end else ResultText := '{"error":"WRONG_ACTIVE_COMPONENT"}';
    end else ResultText := '{"error":"COMPONENT_NOT_FOUND"}';
  end else ResultText := '{"error":"NO_LIBRARY"}';
end else ResultText := '{"error":"DOCUMENT_NOT_OPEN"}';
